/* ----------------------------------------------------------------------------
   2. HÀM TIỆN ÍCH
   ---------------------------------------------------------------------------- */

const formatVND = (n) => `${Math.round(n).toLocaleString('vi-VN')}đ`;
const fmtNum = (n) => (Math.round(n * 10) / 10).toLocaleString('vi-VN');
const fmtKcal = (n) => Math.round(n).toLocaleString('vi-VN');

const EMPTY_TOTALS = { price: 0, calories: 0, protein: 0, carbs: 0, fat: 0 };

/**
 * Tính tổng tiền / calo / macros của món tự thiết kế.
 * selection = { [ingredientId]: grams }
 */
function calcCustom(selection) {
  return Object.entries(selection).reduce(
    (acc, [id, grams]) => {
      const ing = INGREDIENT_MAP[id];
      if (!ing) return acc;
      const f = grams / 100;
      acc.price += ing.pricePer100g * f;
      acc.calories += ing.calPer100g * f;
      acc.protein += ing.proteinPer100g * f;
      acc.carbs += ing.carbsPer100g * f;
      acc.fat += ing.fatPer100g * f;
      return acc;
    },
    { ...EMPTY_TOTALS }
  );
}

