function Logo() {
  return (
    <div className="flex items-center gap-2" aria-label="FIT BOX - Eat Clean. Live Fit.">
      <img src={FITBOX_LOGO} alt="FIT BOX - Eat Clean. Live Fit." className="h-11 w-11 rounded-full object-contain" />
      <div className="leading-none">
        <div className="flex items-center gap-1 text-xl font-extrabold tracking-tight text-green-800">FIT<span className="rounded-md bg-green-700 px-1.5 py-0.5 text-white">BOX</span></div>
        <p className="mt-1 text-xs font-medium italic text-green-700">Eat Clean. Live Fit.</p>
      </div>
    </div>
  );
}

/** Ảnh có fallback 3 tầng: ảnh gốc -> placehold.co -> icon */
function SmartImage({ src, alt, label, className = '' }) {
  const [stage, setStage] = useState(src ? 0 : 1);
  useEffect(() => setStage(src ? 0 : 1), [src]);

  if (stage >= 2) {
    return (
      <div
        role="img"
        aria-label={alt}
        className={`flex items-center justify-center bg-green-50 text-green-700 ${className}`}
      >
        <Utensils className="h-8 w-8 opacity-60" />
      </div>
    );
  }
  return (
    <img
      src={stage === 0 ? src : placeholderUrl(label)}
      alt={alt}
      loading="lazy"
      onError={() => setStage((s) => s + 1)}
      className={className}
    />
  );
}

function MacroRow({ data }) {
  return (
    <div className="grid grid-cols-3 gap-2">
      {MACROS.map((m) => (
        <div key={m.key} className="rounded-lg bg-stone-50 px-2 py-1.5 text-center">
          <div className="flex items-center justify-center gap-1 text-xs text-stone-500">
            <span className={`h-2 w-2 rounded-full ${m.dot}`} />
            {m.label}
          </div>
          <div className="text-sm font-semibold tabular-nums text-stone-800">{fmtNum(data[m.key])}g</div>
        </div>
      ))}
    </div>
  );
}

function QtyStepper({ value, onChange, min = 1, max = MAX_QTY }) {
  return (
    <div className="inline-flex items-center rounded-full border border-stone-300 bg-white" role="group" aria-label="Số lượng">
      <button
        type="button"
        onClick={() => onChange(Math.max(min, value - 1))}
        disabled={value <= min}
        aria-label="Giảm số lượng"
        className="flex h-8 w-8 items-center justify-center rounded-full text-stone-600 hover:bg-stone-100 disabled:cursor-not-allowed disabled:opacity-40"
      >
        <Minus className="h-4 w-4" />
      </button>
      <span className="w-7 text-center text-sm font-semibold tabular-nums" aria-live="polite">{value}</span>
      <button
        type="button"
        onClick={() => onChange(Math.min(max, value + 1))}
        disabled={value >= max}
        aria-label="Tăng số lượng"
        className="flex h-8 w-8 items-center justify-center rounded-full text-stone-600 hover:bg-stone-100 disabled:cursor-not-allowed disabled:opacity-40"
      >
        <Plus className="h-4 w-4" />
      </button>
    </div>
  );
}

function Tabs({ tab, onChange, className = '' }) {
  return (
    <div role="tablist" aria-label="Chọn cách đặt món" className={`flex rounded-full bg-stone-100 p-1 ${className}`}>
      {TABS.map((t) => {
        const Icon = t.icon;
        const active = tab === t.id;
        return (
          <button
            key={t.id}
            type="button"
            role="tab"
            aria-selected={active}
            onClick={() => onChange(t.id)}
            className={`flex flex-1 items-center justify-center gap-2 rounded-full px-3 py-2 text-sm font-semibold transition ${
              active ? 'bg-green-700 text-white shadow' : 'text-stone-600 hover:text-green-800'
            }`}
          >
            <Icon className="h-4 w-4" />
            {t.label}
          </button>
        );
      })}
    </div>
  );
}

/* ----------------------------------------------------------------------------
   4. TAB 1 — THỰC ĐƠN CÓ SẴN
   ---------------------------------------------------------------------------- */

function PresetCard({ meal, onAdd }) {
  const [qty, setQty] = useState(1);
  const [rice, setRice] = useState('white');
  const isRice = meal.category === 'rice';

  const handleAdd = () => {
    onAdd({
      key: `preset-${meal.id}-${isRice ? rice : 'na'}`,
      type: 'preset',
      name: meal.name,
      image: meal.image,
      option: isRice ? RICE_TYPES.find((r) => r.id === rice).label : null,
      unitPrice: meal.price,
      calories: meal.calories,
      protein: meal.protein,
      carbs: meal.carbs,
      fat: meal.fat,
      qty,
    });
    setQty(1);
  };

  return (
    <article className="flex flex-col overflow-hidden rounded-2xl border border-stone-200 bg-white shadow-sm transition hover:shadow-md">
      <div className="relative bg-green-50" style={{ aspectRatio: '4 / 3' }}>
        <SmartImage
          src={meal.image || FOOD_IMAGES[(meal.id - 1) % FOOD_IMAGES.length]}
          alt={meal.name}
          label={`FIT BOX ${isRice ? 'Healthy Rice' : 'Healthy Tacos'}`}
          className="h-full w-full object-cover"
        />
        <div className="absolute right-3 top-3 flex flex-col items-end gap-1.5">
          {meal.vegan && (
            <span className="inline-flex items-center gap-1 rounded-full bg-green-700 px-2.5 py-1 text-xs font-semibold text-white shadow">
              <Sprout className="h-3 w-3" /> Thuần chay
            </span>
          )}
          {meal.badge && (
            <span className="rounded-full bg-amber-200 px-2.5 py-1 text-xs font-semibold text-amber-900 shadow">
              {meal.badge}
            </span>
          )}
        </div>
      </div>

      <div className="flex flex-1 flex-col gap-3 p-4">
        <div>
          <h3 className="text-base font-bold leading-snug text-stone-900">{meal.name}</h3>
          <p className="mt-1 text-sm leading-relaxed text-stone-500">{meal.description}</p>
        </div>

        <div className="flex items-center justify-between">
          <span className="inline-flex items-center gap-1 rounded-full bg-orange-50 px-2.5 py-1 text-sm font-semibold text-orange-600">
            <Flame className="h-4 w-4" />
            {fmtKcal(meal.calories)} kcal
          </span>
          <span className="text-lg font-extrabold text-green-700">{formatVND(meal.price)}</span>
        </div>

        <MacroRow data={meal} />

        {isRice && (
          <div role="radiogroup" aria-label="Loại cơm" className="flex rounded-full bg-amber-50 p-1 text-sm">
            {RICE_TYPES.map((r) => (
              <button
                key={r.id}
                type="button"
                role="radio"
                aria-checked={rice === r.id}
                onClick={() => setRice(r.id)}
                className={`flex-1 rounded-full px-3 py-1.5 font-medium transition ${
                  rice === r.id ? 'bg-white text-green-800 shadow-sm' : 'text-amber-800 hover:text-green-800'
                }`}
              >
                {r.label}
              </button>
            ))}
          </div>
        )}

        <div className="mt-auto flex items-center gap-3 pt-1">
          <QtyStepper value={qty} onChange={setQty} />
          <button
            type="button"
            onClick={handleAdd}
            className="flex flex-1 items-center justify-center gap-2 rounded-full bg-green-600 px-4 py-2.5 text-sm font-semibold text-white transition hover:bg-green-700 active:scale-95"
          >
            <Plus className="h-4 w-4" />
            Thêm vào giỏ hàng
          </button>
        </div>
      </div>
    </article>
  );
}

function MenuTab({ onAdd }) {
  const [filter, setFilter] = useState('all');

  const meals = useMemo(
    () =>
      PRESET_MEALS.filter((m) => {
        if (filter === 'all') return true;
        if (filter === 'vegan') return m.vegan;
        return m.category === filter;
      }),
    [filter]
  );

  return (
    <section aria-labelledby="menu-title">
      <div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
        <div>
          <h2 id="menu-title" className="text-2xl font-extrabold text-stone-900">Thực đơn có sẵn</h2>
          <p className="mt-1 text-sm text-stone-500">{meals.length} món · Chọn loại cơm, số lượng rồi thêm vào giỏ.</p>
        </div>
        <div className="-mx-4 flex gap-2 overflow-x-auto px-4 pb-1 sm:mx-0 sm:px-0">
          {FILTERS.map((f) => (
            <button
              key={f.id}
              type="button"
              aria-pressed={filter === f.id}
              onClick={() => setFilter(f.id)}
              className={`shrink-0 rounded-full border px-4 py-1.5 text-sm font-medium transition ${
                filter === f.id
                  ? 'border-green-700 bg-green-700 text-white'
                  : 'border-stone-300 bg-white text-stone-600 hover:border-green-500 hover:text-green-800'
              }`}
            >
              {f.label}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-3">
        {meals.map((meal) => (
          <PresetCard key={meal.id} meal={meal} onAdd={onAdd} />
        ))}
      </div>
    </section>
  );
}

/* ----------------------------------------------------------------------------
   5. TAB 2 — TỰ THIẾT KẾ MÓN (logic chính)
   ---------------------------------------------------------------------------- */

function IngredientRow({ ing, grams, defaultGrams, onToggle, onGrams }) {
  const selected = grams != null;

  return (
    <div
      className={`flex items-center gap-3 rounded-xl border p-3 transition ${
        selected
          ? 'border-green-600 bg-green-50 ring-1 ring-green-600'
          : 'border-stone-200 bg-white hover:border-green-300'
      }`}
    >
      <button
        type="button"
        role="checkbox"
        aria-checked={selected}
        aria-label={`${selected ? 'Bỏ chọn' : 'Chọn'} ${ing.name}`}
        onClick={() => onToggle(ing.id)}
        className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-md border-2 transition ${
          selected ? 'border-green-600 bg-green-600 text-white' : 'border-stone-300 bg-white text-transparent'
        }`}
      >
        <Check className="h-4 w-4" />
      </button>

      <div className="min-w-0 flex-1 cursor-pointer" onClick={() => onToggle(ing.id)}>
        <div className="flex items-center gap-1.5">
          <span className="text-sm font-semibold leading-snug text-stone-800">{ing.name}</span>
          {ing.vegan && <Sprout className="h-3.5 w-3.5 shrink-0 text-green-600" aria-label="Thuần chay" />}
        </div>
        <p className="text-xs text-stone-500">
          {ing.calPer100g} kcal · P {fmtNum(ing.proteinPer100g)} · C {fmtNum(ing.carbsPer100g)} · F {fmtNum(ing.fatPer100g)}
          <span className="text-stone-400"> /100g</span>
        </p>
        <p className="text-xs font-medium text-green-700">{formatVND(ing.pricePer100g)}/100g</p>
      </div>

      <div className="flex shrink-0 flex-col items-end gap-1">
        <div className="relative">
          <select
            aria-label={`Định lượng ${ing.name}`}
            value={grams ?? defaultGrams}
            onChange={(e) => onGrams(ing.id, Number(e.target.value))}
            className="appearance-none rounded-lg border border-stone-300 bg-white py-1.5 pl-3 pr-8 text-sm font-medium text-stone-700 focus:outline-none focus:ring-2 focus:ring-green-500"
          >
            {PORTION_OPTIONS.map((g) => (
              <option key={g} value={g}>{g}g</option>
            ))}
          </select>
          <ChevronDown className="pointer-events-none absolute right-2 top-1/2 h-4 w-4 -translate-y-1/2 text-stone-500" />
        </div>
        <span className="h-4 text-xs font-semibold tabular-nums text-green-700">
          {selected ? formatVND((ing.pricePer100g * grams) / 100) : ''}
        </span>
      </div>
    </div>
  );
}

function CustomBuilder({ selection, setSelection, onAdd }) {
  // Tính lại tức thì mỗi khi chọn / bỏ chọn nguyên liệu hoặc đổi gram
  const totals = useMemo(() => calcCustom(selection), [selection]);

  const selectedItems = useMemo(
    () =>
      GROUPS.flatMap((g) =>
        INGREDIENTS[g.key]
          .filter((i) => selection[i.id] != null)
          .map((i) => ({ ...i, group: g.key, grams: selection[i.id] }))
      ),
    [selection]
  );

  const count = selectedItems.length;
  const canAdd = count >= 1; // chỉ cần tối thiểu 1 nguyên liệu bất kỳ

  const energy = useMemo(() => {
    const p = totals.protein * 4;
    const c = totals.carbs * 4;
    const f = totals.fat * 9;
    const sum = p + c + f;
    return { p, c, f, sum };
  }, [totals]);
  const pct = (v) => (energy.sum > 0 ? Math.round((v / energy.sum) * 100) : 0);

  const toggle = (id) =>
    setSelection((prev) => {
      const next = { ...prev };
      if (next[id] != null) delete next[id];
      else next[id] = DEFAULT_GRAMS[INGREDIENT_MAP[id].group];
      return next;
    });

  // Đổi gram của nguyên liệu chưa chọn => tự động chọn luôn với số gram đó
  const setGrams = (id, g) => setSelection((prev) => ({ ...prev, [id]: g }));
  const clearAll = () => setSelection({});

  const handleAdd = () => {
    if (!canAdd) return;
    const signature = Object.entries(selection)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([id, g]) => `${id}:${g}`)
      .join('|');

    onAdd({
      key: `custom-${signature}`,
      type: 'custom',
      name: 'Món tự thiết kế',
      unitPrice: totals.price,
      calories: totals.calories,
      protein: totals.protein,
      carbs: totals.carbs,
      fat: totals.fat,
      items: selectedItems.map((i) => ({
        id: i.id,
        name: i.name,
        grams: i.grams,
        price: (i.pricePer100g * i.grams) / 100,
      })),
      qty: 1,
    });
  };

  const addBtnCls = canAdd
    ? 'bg-green-600 text-white shadow-md hover:bg-green-700 active:scale-95'
    : 'cursor-not-allowed bg-stone-200 text-stone-400';

  return (
    <section aria-labelledby="custom-title">
      <div className="mb-6">
        <h2 id="custom-title" className="text-2xl font-extrabold text-stone-900">Tự thiết kế món</h2>
        <p className="mt-1 text-sm text-stone-500">
          Mix nguyên liệu theo ý bạn — không bắt buộc phải có tinh bột hay đạm. Chỉ cần chọn tối thiểu 1 nguyên liệu.
        </p>
      </div>

      <div className="grid grid-cols-1 gap-8 lg:grid-cols-3">
        {/* Danh sách nguyên liệu theo 4 nhóm */}
        <div className="space-y-8 lg:col-span-2">
          {GROUPS.map((g) => {
            const Icon = g.icon;
            const picked = INGREDIENTS[g.key].filter((i) => selection[i.id] != null).length;
            return (
              <section key={g.key} aria-labelledby={`grp-${g.key}`}>
                <div className="mb-3 flex items-center justify-between">
                  <h3 id={`grp-${g.key}`} className="flex items-center gap-2 text-lg font-bold text-stone-900">
                    <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-amber-100 text-amber-800">
                      <Icon className="h-5 w-5" />
                    </span>
                    {g.title}
                    <span className="text-sm font-medium text-stone-400">({g.subtitle})</span>
                  </h3>
                  <span
                    className={`rounded-full px-2.5 py-0.5 text-xs font-semibold ${
                      picked > 0 ? 'bg-green-100 text-green-800' : 'bg-stone-100 text-stone-500'
                    }`}
                  >
                    {picked > 0 ? `Đã chọn ${picked}` : 'Không bắt buộc'}
                  </span>
                </div>
                <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                  {INGREDIENTS[g.key].map((ing) => (
                    <IngredientRow
                      key={ing.id}
                      ing={ing}
                      grams={selection[ing.id]}
                      defaultGrams={g.defaultGrams}
                      onToggle={toggle}
                      onGrams={setGrams}
                    />
                  ))}
                </div>
              </section>
            );
          })}
        </div>

        {/* Tóm tắt real-time */}
        <aside className="h-fit rounded-2xl border border-amber-200 bg-white p-5 shadow-sm lg:sticky lg:top-24">
          <div className="flex items-center justify-between">
            <h3 className="flex items-center gap-2 text-lg font-bold text-stone-900">
              <ChefHat className="h-5 w-5 text-green-700" />
              Bát của bạn
            </h3>
            {count > 0 && (
              <button
                type="button"
                onClick={clearAll}
                className="inline-flex items-center gap-1 text-sm text-stone-500 hover:text-red-600"
              >
                <RotateCcw className="h-4 w-4" /> Xóa hết
              </button>
            )}
          </div>

          {count === 0 ? (
            <div className="mt-4 rounded-xl border border-dashed border-amber-300 bg-amber-50 p-4 text-center text-sm text-amber-900">
              Chọn ít nhất 1 nguyên liệu để bắt đầu thiết kế món.
            </div>
          ) : (
            <ul className="mt-4 divide-y divide-stone-100 text-sm">
              {selectedItems.map((i) => (
                <li key={i.id} className="flex items-center justify-between gap-2 py-2">
                  <span className="min-w-0 flex-1 text-stone-700">
                    {i.name} <span className="text-stone-400">· {i.grams}g</span>
                  </span>
                  <span className="font-medium tabular-nums text-stone-800">
                    {formatVND((i.pricePer100g * i.grams) / 100)}
                  </span>
                  <button
                    type="button"
                    onClick={() => toggle(i.id)}
                    aria-label={`Bỏ ${i.name}`}
                    className="rounded-full p-1 text-stone-400 hover:bg-red-50 hover:text-red-600"
                  >
                    <X className="h-4 w-4" />
                  </button>
                </li>
              ))}
            </ul>
          )}

          <div className="mt-4 rounded-xl bg-green-50 p-4" aria-live="polite">
            <div className="flex items-end justify-between gap-3">
              <div>
                <p className="text-xs font-semibold uppercase tracking-wide text-stone-500">Tổng tiền</p>
                <p className="text-2xl font-extrabold tabular-nums text-green-800">{formatVND(totals.price)}</p>
              </div>
              <div className="text-right">
                <p className="text-xs font-semibold uppercase tracking-wide text-stone-500">Tổng calo</p>
                <p className="flex items-center justify-end gap-1 text-2xl font-extrabold tabular-nums text-orange-600">
                  <Flame className="h-5 w-5" />
                  {fmtKcal(totals.calories)}
                  <span className="text-sm font-semibold">kcal</span>
                </p>
              </div>
            </div>
          </div>

          <div className="mt-3">
            <MacroRow data={totals} />
          </div>

          {/* Tỷ lệ năng lượng từ Protein / Carbs / Fat */}
          <div className="mt-3">
            <div className="flex h-2 overflow-hidden rounded-full bg-stone-100" aria-hidden="true">
              {energy.sum > 0 && (
                <>
                  <div className="bg-green-500 transition-all" style={{ width: `${(energy.p / energy.sum) * 100}%` }} />
                  <div className="bg-amber-400 transition-all" style={{ width: `${(energy.c / energy.sum) * 100}%` }} />
                  <div className="bg-orange-400 transition-all" style={{ width: `${(energy.f / energy.sum) * 100}%` }} />
                </>
              )}
            </div>
            <p className="mt-1.5 text-center text-xs text-stone-500">
              Năng lượng từ: Protein {pct(energy.p)}% · Carbs {pct(energy.c)}% · Fat {pct(energy.f)}%
            </p>
          </div>

          <button
            type="button"
            disabled={!canAdd}
            onClick={handleAdd}
            className={`mt-4 flex w-full items-center justify-center gap-2 rounded-full px-4 py-3 text-sm font-bold transition ${addBtnCls}`}
          >
            <ShoppingBag className="h-4 w-4" />
            Thêm vào giỏ
          </button>
        </aside>
      </div>

      {/* Thanh cố định phía dưới cho mobile */}
      <div className="fixed inset-x-0 bottom-0 z-30 border-t border-stone-200 bg-white/95 px-4 py-3 shadow-lg backdrop-blur lg:hidden">
        <div className="mx-auto flex max-w-6xl items-center gap-3">
          <div className="min-w-0 flex-1">
            <p className="text-lg font-extrabold leading-tight tabular-nums text-green-800">{formatVND(totals.price)}</p>
            <p className="truncate text-xs text-stone-500">
              {fmtKcal(totals.calories)} kcal · P {fmtNum(totals.protein)}g · C {fmtNum(totals.carbs)}g · F {fmtNum(totals.fat)}g
            </p>
          </div>
          <button
            type="button"
            disabled={!canAdd}
            onClick={handleAdd}
            className={`flex shrink-0 items-center gap-2 rounded-full px-5 py-3 text-sm font-bold transition ${addBtnCls}`}
          >
            <ShoppingBag className="h-4 w-4" />
            Thêm vào giỏ
          </button>
        </div>
      </div>
    </section>
  );
}

